// 1. جلب بيانات ملفات Google Drive مباشرة من العقدة الخاصة بها
const driveItems = $items("Search files and folders") || [];

// 2. جلب صفوف Google Sheet مباشرة من العقدة الخاصة بها
const sheetItems = $items("Get row(s) in sheet") || [];

// 3. تجميع كافة الـ IDs الموجودة بالفعل في الشيت
const processedIds = new Set();
for (const item of sheetItems) {
  const row = item.json;
  // البحث عن حقل الـ ID بغض النظر عن حالة الأحرف
  const idValue = row.ID || row.id || row.Id;
  if (idValue) {
    processedIds.add(String(idValue).trim());
  }
}

// 4. فلترة ملفات Drive للحصول على الملفات الجديدة فقط
const newFiles = [];
for (const item of driveItems) {
  const file = item.json;
  const fileId = String(file.id || file.Id).trim();

  // إذا لم يكن الـ ID موجوداً في الشيت، إذن هو ملف جديد
  if (fileId && !processedIds.has(fileId)) {
    newFiles.push({
      json: {
        fileId: fileId,
        fileName: file.name || file.Name,
        Id: fileId,
        Name: file.name || file.Name
      }
    });
  }
}

console.log(`إجمالي ملفات درايف: ${driveItems.length}`);
console.log(`إجمالي ملفات الشيت: ${sheetItems.length}`);
console.log(`الملفات الجديدة المطلوبة: ${newFiles.length}`);

// إرجاع الملفات الجديدة فقط لتكملة الوركفلو
return newFiles;

