// دالة مرنة للبحث عن السطر واستخراج قيمته
function getCleanLine(text, label) {
  if (!text) return "غير محدد";
  const lines = text.split("\n");
  for (let line of lines) {
    if (line.toLowerCase().includes(label.toLowerCase())) {
      let parts = line.split(":");
      if (parts.length > 1) {
        return parts.slice(1).join(":").replace(/[\*]/g, "").trim();
      }
    }
  }
  return "غير محدد";
}

// دالة تنظيف الرقم القومي وتصفية الـ 14 رقم فقط
function cleanNationalId(rawText) {
  if (!rawText || rawText === "غير محدد") return "⚠️ فشل الاستخراج - يتطلب مراجعة يدوية";

  // 1. البحث عن 14 رقم متتاليين (الصيغة القياسية للرقم القومي)
  const match14 = rawText.match(/\d{14}/);
  if (match14) return match14[0];

  // 2. إذا لم يجد 14 رقم متصلين، يستخرج الأرقام ويحذف أي نصوص وأقواس جانبية
  const digitsOnly = rawText.replace(/[^\d]/g, "");
  if (digitsOnly.length >= 10) return digitsOnly;

  // 3. مسح الجمل والأقواس التوضيحية كخيار أخير
  return rawText.replace(/\(.*?\)/g, "").trim();
}

