  for (const item of existingRows) {
    const row = item.json;

    // تجنب الاستجابات الفارغة
    if (!row || !row.national_id || Object.keys(row).length === 0) continue;

    // 👈 قراءة الحقول بالمسميات الدقيقة الموجودة في الشيت الخاص بك
    const sheetMed = String(row.requested_medication || row.medication_name || '').trim().toLowerCase();
    const status = String(row.preauth_status || row.status || '').trim();

    // معالجة تاريخ الانتهاء (لو غير موجود بالشيت يفترض أنه ساري بناءً على الحالة)
    const expiryDate = row.expiry_date ? new Date(row.expiry_date) : null;
    const isNotExpired = expiryDate ? expiryDate >= currentDate : true;

    // فصل أسماء الأدوية إلى كلمات لتسهيل المطابقة الجزئية
    const medWords = med.split(/[ -/]+/).filter(w => w.length > 2); // كلمات الدواء المطلوب
    const sheetMedWords = sheetMed.split(/[ -/()]+/).filter(w => w.length > 2); // كلمات الدواء في الشيت

    // فحص إذا كان هناك على الأقل كلمة واحدة أساسية متطابقة (مثل "lantus")
    let isSameMedication = false;
    for (const word of medWords) {
      if (sheetMedWords.includes(word)) {
        isSameMedication = true;
        break;
      }
    }
    const isApprovedStatus = status.includes('موافق') || status === 'مقبول' || status === 'Approved';

    if (isSameMedication && isApprovedStatus && isNotExpired) {
      hasActiveApproval = true;
      activeApprovalDetails = {
        approval_id: row.message_id || row.row_number || 'موافقة سارية',
        medication: row.requested_medication,
        patient_name: row.patient_name,
        preauth_status: row.preauth_status,
        timestamp: row.timestamp
      };
      break;
    }
  }

  if (hasActiveApproval) {
    duplicateApprovalsFound.push(activeApprovalDetails);
  } else {
    passedMedications.push({
      medication: med
    });
  }
});

// 4. إخراج النتيجة
const hasDuplicates = duplicateApprovalsFound.length > 0;

return [{
  json: {
    has_active_approval: hasDuplicates, // سيعطي الآن true بنجاح!
    approval_info: duplicateApprovalsFound, // سيحتوي على تفاصيل "لانتوس" والموافقة السابقة
    medications_passed: passedMedications,
    extracted_data: newRequest
  },
  // تمرير الـ Binary File الأصلي للنود التالية
  binary: $input.item.binary
}];

